def solve(assignments, remaining_suspects, remaining_rooms, remaining_weapons, remaining_times):
    if len(assignments) == 5:
        return assignments

    for suspect in list(remaining_suspects):
        for room in list(remaining_rooms):
            for weapon in list(remaining_weapons):
                for time in list(remaining_times):
                    candidate = {
                        'suspect': suspect,
                        'room': room,
                        'weapon': weapon,
                        'time': time,
                    }

                    if not respects_clues(candidate, assignments):
                        continue

                    assignments.append(candidate)
                    result = solve(
                        assignments,
                        remaining_suspects - {suspect},
                        remaining_rooms - {room},
                        remaining_weapons - {weapon},
                        remaining_times - {time},
                    )
                    if result:
                        return result
                    assignments.pop()

    return None
